        await sdlcService.updateAdoDesignSync(syncRecord.id, {
          syncStatus: result.errors.length > 0 ? 'failed' : 'completed',
          syncedItemsCount: result.syncedCount,
          errorMessage: result.errors.length > 0 ? result.errors.join('; ') : null,
        });

