  ): Promise<any> {
    const url = `https://dev.azure.com/${this.organization}/${this.project}/_apis/git/repositories/${repositoryId}/items?scopePath=${encodeURIComponent(scopePath)}&recursionLevel=${recursionLevel}&api-version=7.0`;

