export const sdlcDocuments = mysqlTable("sdlc_documents", {
  id: varchar("id", { length: 36 }).primaryKey().$defaultFn(() => crypto.randomUUID()),
  projectId: varchar("project_id", { length: 36 }).notNull(),
  phaseNumber: int("phase_number").notNull(),
