      setPriority("medium");
      setStatus("");
      setItemType("");
      setStoryPoints("");
      setContent("");
    }
  }, [open]);

  // Fetch work items
  const { data: items = [], isLoading } = useQuery<WorkItem[]>({
    queryKey: [`/api/sdlc/projects/${projectId}/phases/${phaseId}/${type}`],
    enabled: open,
  });

  // Create work item mutation
  const createMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest("POST", `/api/sdlc/projects/${projectId}/phases/${phaseId}/${type}`, data);
    },
    onSuccess: (response: any) => {
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/phases/${phaseId}/${type}`] });
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/details`] });
      toast({ title: `${getTypeLabel(type)} created successfully` });

      // Check if a phase was unlocked
      if (response?._phaseUnlocked?.unlocked) {
        toast({
          title: "✅ Phase Unlocked!",
          description: `${response._phaseUnlocked.phaseName} — You can now proceed.`,
        });
      }

      resetForm();
    },
    onError: () => {
      toast({ 
        title: `Failed to create ${getTypeLabel(type).toLowerCase()}`,
        variant: "destructive" 
      });
    },
  });

  // Delete work item mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/sdlc/${type}/${id}`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/phases/${phaseId}/${type}`] });
      toast({ title: `${getTypeLabel(type)} deleted successfully` });
    },
  });

  const resetForm = () => {
    setTitle("");
    setDescription("");
    setPriority("medium");
    setStatus("");
    setItemType("");
    setStoryPoints("");
    setContent("");
  };

  const handleCreate = () => {
    if (!title.trim()) {
      toast({ title: "Title is required", variant: "destructive" });
      return;
    }

    const baseData = {
      title: title.trim(),
      description: description.trim() || null,
      priority,
    };

    let data: any = baseData;

    switch (type) {
      case "issues":
        data = { ...baseData, status: status || "open" };
        break;
      case "epics":
        data = { ...baseData, status: status || "planned", featureCount: 0 };
        break;
      case "requirements":
        data = { ...baseData, type: itemType || "functional", status: status || "draft" };
        break;
      case "backlog":
        data = { 
          ...baseData, 
          type: itemType || "story", 
          status: status || "backlog",
          storyPoints: storyPoints ? parseInt(storyPoints) : null,
        };
        break;
      case "documents":
        data = { 
          title: title.trim(), 
          content: content.trim() || null,
          type: itemType || "general",
        };
        break;
    }

    createMutation.mutate(data);
  };

  const getTypeLabel = (type: WorkItemType): string => {
    const labels = {
      issues: "Issue",
      epics: "Epic",
      requirements: "Requirement",
      backlog: "Backlog Item",
      documents: "Document",
    };
    return labels[type];
  };

  const getStatusOptions = () => {
    switch (type) {
      case "issues":
        return [
          { value: "open", label: "Open" },
          { value: "in_progress", label: "In Progress" },
          { value: "resolved", label: "Resolved" },
          { value: "closed", label: "Closed" },
        ];
      case "epics":
        return [
          { value: "planned", label: "Planned" },
          { value: "in_progress", label: "In Progress" },
          { value: "completed", label: "Completed" },
        ];
      case "requirements":
        return [
          { value: "draft", label: "Draft" },
          { value: "approved", label: "Approved" },
          { value: "implemented", label: "Implemented" },
        ];
      case "backlog":
        return [
          { value: "backlog", label: "Backlog" },
          { value: "ready", label: "Ready" },
          { value: "in_progress", label: "In Progress" },
          { value: "done", label: "Done" },
        ];
      default:
        return [];
    }
  };

  const getTypeOptions = () => {
    switch (type) {
      case "requirements":
        return [
          { value: "functional", label: "Functional" },
          { value: "non_functional", label: "Non-Functional" },
          { value: "business", label: "Business" },
        ];
      case "backlog":
        return [
          { value: "story", label: "Story" },
          { value: "bug", label: "Bug" },
          { value: "task", label: "Task" },
        ];
      case "documents":
        return [
          { value: "general", label: "General" },
          { value: "technical", label: "Technical" },
          { value: "user_guide", label: "User Guide" },
          { value: "api_doc", label: "API Documentation" },
        ];
      default:
        return [];
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle data-testid="dialog-title">{getTypeLabel(type)} Management</DialogTitle>
          <DialogDescription>
            {phaseName && `Phase: ${phaseName} • `}View and manage {type} for this project
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          {/* Create New Form */}
          <div className="space-y-4 p-4 border rounded-md">
            <h3 className="font-semibold">Create New {getTypeLabel(type)}</h3>

            <div className="space-y-2">
              <Label htmlFor="title">Title</Label>
              <Input
                id="title"
                data-testid="input-title"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder={`Enter ${type.slice(0, -1)} title`}
              />
            </div>

            {type !== "documents" && (
              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  data-testid="input-description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Enter description (optional)"
                  rows={3}
                />
              </div>
            )}

            {type === "documents" && (
              <div className="space-y-2">
                <Label htmlFor="content">Content</Label>
                <Textarea
                  id="content"
                  data-testid="input-content"
                  value={content}
                  onChange={(e) => setContent(e.target.value)}
                  placeholder="Enter document content"
                  rows={5}
                />
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              {type !== "documents" && (
                <div className="space-y-2">
                  <Label htmlFor="priority">Priority</Label>
                  <Select value={priority} onValueChange={setPriority}>
                    <SelectTrigger id="priority" data-testid="select-priority">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low</SelectItem>
                      <SelectItem value="medium">Medium</SelectItem>
                      <SelectItem value="high">High</SelectItem>
                      {type === "issues" && <SelectItem value="critical">Critical</SelectItem>}
                    </SelectContent>
                  </Select>
                </div>
              )}

              {getStatusOptions().length > 0 && (
                <div className="space-y-2">
                  <Label htmlFor="status">Status</Label>
                  <Select value={status} onValueChange={setStatus}>
                    <SelectTrigger id="status" data-testid="select-status">
                      <SelectValue placeholder="Select status" />
                    </SelectTrigger>
                    <SelectContent>
                      {getStatusOptions().map((opt) => (
                        <SelectItem key={opt.value} value={opt.value}>
                          {opt.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}

              {getTypeOptions().length > 0 && (
                <div className="space-y-2">
                  <Label htmlFor="type">Type</Label>
                  <Select value={itemType} onValueChange={setItemType}>
                    <SelectTrigger id="type" data-testid="select-type">
                      <SelectValue placeholder="Select type" />
                    </SelectTrigger>
                    <SelectContent>
                      {getTypeOptions().map((opt) => (
                        <SelectItem key={opt.value} value={opt.value}>
                          {opt.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}

              {type === "backlog" && (
                <div className="space-y-2">
                  <Label htmlFor="storyPoints">Story Points</Label>
                  <Input
                    id="storyPoints"
                    data-testid="input-story-points"
                    type="number"
                    min="0"
                    value={storyPoints}
                    onChange={(e) => setStoryPoints(e.target.value)}
                    placeholder="0"
                  />
                </div>
              )}
            </div>

            <Button 
              onClick={handleCreate} 
              disabled={createMutation.isPending}
              data-testid="button-create"
              className="w-full"
            >
              {createMutation.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Creating...
                </>
              ) : (
                <>
                  <Plus className="h-4 w-4 mr-2" />
                  Create {getTypeLabel(type)}
                </>
              )}
            </Button>
          </div>

          {/* Items List */}
          <div className="space-y-3">
            <h3 className="font-semibold">Existing {getTypeLabel(type)}s</h3>
            {isLoading ? (
              <div className="flex items-center justify-center p-8">
                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              </div>
            ) : items.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center p-8">
                No {type} yet. Create one above to get started.
              </p>
            ) : (
              <div className="space-y-2 max-h-96 overflow-y-auto">
                {items.map((item: any) => (
                  <div
                    key={item.id}
                    className="flex items-start justify-between p-3 border rounded-md hover-elevate"
                    data-testid={`item-${item.id}`}
                  >
                    <div className="flex-1 min-w-0">
                      <h4 className="font-medium text-sm">{item.title}</h4>
                      {item.description && (
                        <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
                          {item.description}
                        </p>
                      )}
                      {item.content && (
                        <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
                          {item.content}
                        </p>
                      )}
                      <div className="flex items-center gap-2 mt-2">
                        {item.priority && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-muted">
                            {item.priority}
                          </span>
                        )}
                        {item.status && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-muted">
                            {item.status}
                          </span>
                        )}
                        {item.type && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-muted">
                            {item.type}
                          </span>
                        )}
                        {item.storyPoints !== undefined && item.storyPoints !== null && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-muted">
                            {item.storyPoints} pts
                          </span>
                        )}
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => deleteMutation.mutate(item.id)}
                      disabled={deleteMutation.isPending}
                      data-testid={`button-delete-${item.id}`}
                      className="ml-2 shrink-0"
                    >
                      Delete
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/cicd-action-dialog.content:
import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  PlayCircle,
  StopCircle,
  CheckCircle2,
  XCircle,
  Clock,
  Upload,
  Download,
  Terminal,
  FileText,
  Package,
  Rocket,
  Activity,
  TrendingUp,
  AlertCircle,
  Server,
  Zap,
  Flag,
  Eye,
} from "lucide-react";
import { useMutation } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

type ActionType = 
  | "run-cicd"
  | "view-test-report"
  | "publish-package"
  | "trigger-release"
  | "manage-feature-flags"
  | "open-monitoring"
  | "push-code"
  | "create-mr"
  | "review-code"
  | "create-target"
  | "assign-reviewers"
  | "link-jira"
  | "review-design"
  | "upload-diagram"
  | "export-figma"
  | "goto-reports";

interface CICDActionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  actionType: ActionType | null;
  projectId: string;
  projectName: string;
  phaseName: string;
}

type PipelineStage = {
  name: string;
  status: "pending" | "running" | "success" | "failed";
  duration?: string;
  logs?: string[];
};

export function CICDActionDialog({
  open,
  onOpenChange,
  actionType,
  projectId,
  projectName,
  phaseName,
}: CICDActionDialogProps) {
  const { toast } = useToast();
  const [isRunning, setIsRunning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentStage, setCurrentStage] = useState(0);
  const [environment, setEnvironment] = useState("staging");
  const [version, setVersion] = useState("1.0.0");
  const [featureFlags, setFeatureFlags] = useState([
    { id: "1", name: "new-ui-design", enabled: true, rollout: 100 },
    { id: "2", name: "ai-suggestions", enabled: true, rollout: 50 },
    { id: "3", name: "dark-mode-v2", enabled: false, rollout: 0 },
  ]);

  const [pipelineStages, setPipelineStages] = useState<PipelineStage[]>([
    { name: "Build", status: "pending" },
    { name: "Test", status: "pending" },
    { name: "Security Scan", status: "pending" },
    { name: "Deploy", status: "pending" },
  ]);

  const getDialogTitle = () => {
    switch (actionType) {
      case "run-cicd":
        return "Run CI/CD Pipeline";
      case "view-test-report":
        return "Test Reports";
      case "publish-package":
        return "Publish Package";
      case "trigger-release":
        return "Trigger Release";
      case "manage-feature-flags":
        return "Manage Feature Flags";
      case "open-monitoring":
        return "Monitoring Dashboard";
      case "push-code":
        return "Push Code";
      case "create-mr":
        return "Create Merge Request";
      case "review-code":
        return "Review Code";
      case "create-target":
        return "Create Target";
      case "assign-reviewers":
        return "Assign Reviewers";
      case "link-jira":
        return "Link Jira Ticket";
      case "review-design":
        return "Review Design";
      case "upload-diagram":
        return "Upload Architecture Diagram";
      case "export-figma":
        return "Export to Figma";
      case "goto-reports":
        return "Go to Reports";
      default:
        return "Action";
    }
  };

  const getDialogDescription = () => {
    switch (actionType) {
      case "run-cicd":
        return `Execute CI/CD pipeline for ${projectName} - ${phaseName}`;
      case "view-test-report":
        return `View test results and coverage for ${projectName}`;
      case "publish-package":
        return `Publish package to registry for ${projectName}`;
      case "trigger-release":
        return `Deploy ${projectName} to production environment`;
      case "manage-feature-flags":
        return `Control feature rollout for ${projectName}`;
      case "open-monitoring":
        return `Monitor performance and health of ${projectName}`;
      case "push-code":
        return `Push your local changes to the remote repository for ${projectName}`;
      case "create-mr":
        return `Create a new merge request for ${projectName}`;
      case "review-code":
        return `Review pending code changes for ${projectName}`;
      case "create-target":
        return `Create a new epic or target milestone for ${projectName}`;
      case "assign-reviewers":
        return `Assign team members to review work items in ${projectName}`;
      case "link-jira":
        return `Link Jira tickets to work items in ${projectName}`;
      case "review-design":
        return `Review design mockups and assets for ${projectName}`;
      case "upload-diagram":
        return `Upload architecture diagrams and technical documentation for ${projectName}`;
      case "export-figma":
        return `Export design assets to Figma for ${projectName}`;
      case "goto-reports":
        return `View maintenance and performance reports for ${projectName}`;
      default:
        return "";
    }
  };

  const runCICDPipeline = async () => {
    setIsRunning(true);
    setProgress(0);

    const stages = [...pipelineStages];
    for (let i = 0; i < stages.length; i++) {
      setCurrentStage(i);
      stages[i].status = "running";
      setPipelineStages([...stages]);

      await new Promise((resolve) => setTimeout(resolve, 2000));

      const success = Math.random() > 0.1;
      stages[i].status = success ? "success" : "failed";
      stages[i].duration = `${(Math.random() * 30 + 10).toFixed(1)}s`;
      stages[i].logs = [
        `[${new Date().toLocaleTimeString()}] Starting ${stages[i].name}...`,
        `[${new Date().toLocaleTimeString()}] Processing dependencies...`,
        `[${new Date().toLocaleTimeString()}] ${success ? "✓ Completed successfully" : "✗ Failed"}`,
      ];
      setPipelineStages([...stages]);
      setProgress(((i + 1) / stages.length) * 100);

      if (!success) {
        setIsRunning(false);
        toast({
          title: "Pipeline Failed",
          description: `${stages[i].name} stage failed. Check logs for details.`,
          variant: "destructive",
        });
        return;
      }
    }

    setIsRunning(false);
    toast({
      title: "Pipeline Completed",
      description: "All stages completed successfully!",
    });
  };

  const publishPackage = () => {
    toast({
      title: "Package Published",
      description: `Version ${version} published to registry successfully!`,
    });
    onOpenChange(false);
  };

  const triggerRelease = () => {
    toast({
      title: "Release Triggered",
      description: `Deploying to ${environment} environment...`,
    });
    onOpenChange(false);
  };

  const updateFeatureFlag = (id: string, enabled: boolean) => {
    setFeatureFlags(
      featureFlags.map((flag) =>
        flag.id === id ? { ...flag, enabled } : flag
      )
    );
    toast({
      title: "Feature Flag Updated",
      description: `Flag ${featureFlags.find((f) => f.id === id)?.name} ${enabled ? "enabled" : "disabled"}`,
    });
  };

  const renderRunCICD = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="space-y-1">
          <Label>Environment</Label>
          <Select value={environment} onValueChange={setEnvironment}>
            <SelectTrigger className="w-[200px]" data-testid="select-environment">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="development">Development</SelectItem>
              <SelectItem value="staging">Staging</SelectItem>
              <SelectItem value="production">Production</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <Button
          onClick={runCICDPipeline}
          disabled={isRunning}
          data-testid="button-run-pipeline"
        >
          {isRunning ? (
            <>
              <StopCircle className="mr-2 h-4 w-4 animate-spin" />
              Running...
            </>
          ) : (
            <>
              <PlayCircle className="mr-2 h-4 w-4" />
              Run Pipeline
            </>
          )}
        </Button>
      </div>

      <Progress value={progress} className="h-2" data-testid="progress-pipeline" />

      <div className="space-y-3">
        {pipelineStages.map((stage, idx) => (
          <div
            key={idx}
            className={`p-4 rounded-lg border ${
              stage.status === "running" ? "border-primary bg-primary/5" : ""
            }`}
            data-testid={`stage-${idx}`}
          >
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                {stage.status === "pending" && (
                  <Clock className="h-4 w-4 text-muted-foreground" />
                )}
                {stage.status === "running" && (
                  <PlayCircle className="h-4 w-4 text-primary animate-pulse" />
                )}
                {stage.status === "success" && (
                  <CheckCircle2 className="h-4 w-4 text-green-500" />
                )}
                {stage.status === "failed" && (
                  <XCircle className="h-4 w-4 text-destructive" />
                )}
                <span className="font-medium">{stage.name}</span>
              </div>
              <div className="flex items-center gap-3">
                {stage.duration && (
                  <span className="text-xs text-muted-foreground">
                    {stage.duration}
                  </span>
                )}
                <Badge
                  variant={
                    stage.status === "success"
                      ? "default"
                      : stage.status === "failed"
                      ? "destructive"
                      : "secondary"
                  }
                  data-testid={`badge-status-${idx}`}
                >
                  {stage.status}
                </Badge>
              </div>
            </div>
            {stage.logs && stage.logs.length > 0 && (
              <ScrollArea className="h-20 mt-2">
                <div className="bg-muted/50 p-2 rounded font-mono text-xs space-y-1">
                  {stage.logs.map((log, logIdx) => (
                    <div key={logIdx} className="text-muted-foreground">
                      {log}
                    </div>
                  ))}
                </div>
              </ScrollArea>
            )}
          </div>
        ))}
      </div>
    </div>
  );

  const renderTestReport = () => (
    <Tabs defaultValue="summary" className="w-full">
      <TabsList className="grid w-full grid-cols-3">
        <TabsTrigger value="summary" data-testid="tab-summary">
          Summary
        </TabsTrigger>
        <TabsTrigger value="coverage" data-testid="tab-coverage">
          Coverage
        </TabsTrigger>
        <TabsTrigger value="details" data-testid="tab-details">
          Details
        </TabsTrigger>
      </TabsList>

      <TabsContent value="summary" className="space-y-4">
        <div className="grid grid-cols-3 gap-4">
          <div className="p-4 border rounded-lg" data-testid="stat-total-tests">
            <div className="text-2xl font-bold text-green-500">247</div>
            <div className="text-sm text-muted-foreground">Tests Passed</div>
          </div>
          <div className="p-4 border rounded-lg" data-testid="stat-failed-tests">
            <div className="text-2xl font-bold text-destructive">3</div>
            <div className="text-sm text-muted-foreground">Tests Failed</div>
          </div>
          <div className="p-4 border rounded-lg" data-testid="stat-skipped-tests">
            <div className="text-2xl font-bold text-amber-500">5</div>
            <div className="text-sm text-muted-foreground">Tests Skipped</div>
          </div>
        </div>
        <div className="p-4 border rounded-lg">
          <div className="flex items-center justify-between mb-2">
            <span className="font-medium">Overall Success Rate</span>
            <span className="text-xl font-bold text-green-500">98.8%</span>
          </div>
          <Progress value={98.8} className="h-2" />
        </div>
      </TabsContent>

      <TabsContent value="coverage" className="space-y-4">
        <div className="space-y-3">
          {[
            { name: "Lines", coverage: 87.3 },
            { name: "Branches", coverage: 82.1 },
            { name: "Functions", coverage: 91.5 },
            { name: "Statements", coverage: 86.9 },
          ].map((metric, idx) => (
            <div key={idx} className="space-y-2" data-testid={`coverage-${idx}`}>
