export async function createPolicy(req, res, next) {
  try {
    const { policyNumber, type, premium, coverage, startDate, endDate, status, customerId } = req.body;
    const policy = await prisma.policy.create({ data: { policyNumber, type, premium, coverage, startDate: new Date(startDate), endDate: new Date(endDate), status, customerId } });
    res.status(201).json(policy);
  } catch (e) { next(e); }
}

// Simple risk evaluation service for demo purposes
export function evaluateRisk({ age, product, priorClaims }) {
  let risk = (Number(age) || 0) / 10 + (Number(priorClaims) || 0) * 5;
  if (product === 'life') risk += 10;
  if (product === 'home') risk += 5;
  const decision = risk < 10 ? 'approve' : risk < 20 ? 'review' : 'decline';
  return { riskScore: Math.round(risk), decision };
}

