          <tr><th>Name</th><th>Email</th><th>Phone</th><th>Policies</th></tr>
        </thead>
        <tbody>
          {customersSeed.map(c => (
            <tr key={c.id}>
              <td>{c.name}</td>
              <td>{c.email}</td>
              <td>{c.phone}</td>
              <td>{c.policies.join(', ')}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

