import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Check, X, Plus, Trash2, AlertCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import type { AdoSettings } from "@shared/schema";

interface ArtifactsOrganization {
  id: string;
  name: string;
  organizationUrl: string;
  patConfigured: boolean;
}

interface GoldenRepoOrganization {
  id: string;
  name: string;
  organizationUrl: string;
  projectName: string;
  repositoryName: string;
  apiVersion: string;
  patConfigured: boolean;
  createdAt: string;
  updatedAt: string;
}

interface ConversationalUISettings {
  id: string;
  organizationName: string;
  projectName: string;
  apiVersion: string;
  patConfigured: boolean;
}

function ConversationalUISettingsForm() {
  const { toast } = useToast();
  const [formData, setFormData] = useState({
    organizationName: "",
    projectName: "",
    apiVersion: "7.0",
    patToken: "",
  });

  // Fetch conversational UI settings
  const { data: settingsData, isLoading } = useQuery<{ settings: ConversationalUISettings | null }>({
    queryKey: ["/api/conversational-ui-settings"],
  });

  const settings = settingsData?.settings;

  // Update form when settings load
  useEffect(() => {
    if (settings) {
      setFormData({
        organizationName: settings.organizationName || "",
        projectName: settings.projectName || "",
        apiVersion: settings.apiVersion || "7.0",
        patToken: "",
      });
    }
  }, [settings]);

  // Save settings mutation
  const saveMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest("POST", "/api/conversational-ui-settings", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/conversational-ui-settings"] });
      toast({
        title: "Settings Saved",
        description: "Conversational UI ADO settings saved successfully",
      });
      setFormData(prev => ({ ...prev, patToken: "" }));
    },
    onError: (error: any) => {
      toast({
        title: "Save Failed",
        description: error.message || "Failed to save settings",
        variant: "destructive",
      });
    },
  });

  const handleSave = () => {
    if (!formData.organizationName || !formData.projectName) {
      toast({
        title: "Validation Error",
        description: "Organization Name and Project Name are required",
        variant: "destructive",
      });
      return;
    }
    saveMutation.mutate(formData);
  };

  if (isLoading) {
    return (
      <div className="flex justify-center py-12" data-testid="loading-conversational-ui-settings">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="space-y-4">
        <div className="grid gap-4">
          <div className="space-y-2">
            <Label htmlFor="conv-org-name" data-testid="label-organization-name">
              Organization Name <span className="text-destructive">*</span>
            </Label>
            <Input
              id="conv-org-name"
              placeholder="e.g., NOUSBLR"
              value={formData.organizationName}
              onChange={(e) => setFormData(prev => ({ ...prev, organizationName: e.target.value }))}
              data-testid="input-organization-name"
            />
            <p className="text-sm text-muted-foreground">
              Your Azure DevOps organization name (not the full URL)
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="conv-project-name" data-testid="label-project-name">
              Project Name <span className="text-destructive">*</span>
            </Label>
            <Input
              id="conv-project-name"
              placeholder="e.g., GSS-COC-DEVX-FOCUS"
              value={formData.projectName}
              onChange={(e) => setFormData(prev => ({ ...prev, projectName: e.target.value }))}
              data-testid="input-project-name"
            />
            <p className="text-sm text-muted-foreground">
              The Azure DevOps project name for the Conversational UI
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="conv-pat-token" data-testid="label-pat-token">
              Personal Access Token (PAT)
              {settings?.patConfigured && (
                <Badge variant="secondary" className="ml-2" data-testid="badge-pat-configured">
                  <Check className="h-3 w-3 mr-1" />
                  Configured
                </Badge>
              )}
            </Label>
            <Input
              id="conv-pat-token"
              type="password"
              placeholder={settings?.patConfigured ? "Enter new PAT to update" : "Enter your Azure DevOps PAT"}
              value={formData.patToken}
              onChange={(e) => setFormData(prev => ({ ...prev, patToken: e.target.value }))}
              data-testid="input-pat-token"
            />
            <p className="text-sm text-muted-foreground">
              {settings?.patConfigured
                ? "PAT is encrypted and stored securely. Leave blank to keep current PAT."
                : "Your PAT will be encrypted before storage"}
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="conv-api-version" data-testid="label-api-version">
              API Version
            </Label>
            <Input
              id="conv-api-version"
              value={formData.apiVersion}
              onChange={(e) => setFormData(prev => ({ ...prev, apiVersion: e.target.value }))}
              data-testid="input-api-version"
            />
            <p className="text-sm text-muted-foreground">
              Azure DevOps REST API version (default: 7.0)
            </p>
          </div>
        </div>

        <div className="flex justify-end gap-2 pt-4">
          <Button
            onClick={handleSave}
            disabled={saveMutation.isPending}
            data-testid="button-save-conversational-ui-settings"
          >
            {saveMutation.isPending ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Saving...
              </>
            ) : (
              "Save Settings"
            )}
          </Button>
        </div>
      </div>

      {settings && (
        <div className="rounded-lg border p-4 bg-muted/50">
          <h4 className="text-sm font-medium mb-2">Current Configuration</h4>
          <div className="space-y-1 text-sm text-muted-foreground">
            <div className="flex justify-between">
              <span>Organization:</span>
              <span className="font-mono" data-testid="text-current-org">{settings.organizationName}</span>
            </div>
            <div className="flex justify-between">
              <span>Project:</span>
              <span className="font-mono" data-testid="text-current-project">{settings.projectName}</span>
            </div>
            <div className="flex justify-between">
              <span>API Version:</span>
              <span className="font-mono" data-testid="text-current-api-version">{settings.apiVersion}</span>
            </div>
            <div className="flex justify-between">
              <span>PAT Status:</span>
              {settings.patConfigured ? (
                <Badge variant="secondary" className="h-5" data-testid="badge-current-pat-status">
                  <Check className="h-3 w-3 mr-1" />
                  Configured
                </Badge>
              ) : (
                <Badge variant="outline" className="h-5" data-testid="badge-current-pat-not-configured">
                  <X className="h-3 w-3 mr-1" />
                  Not Configured
                </Badge>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default function Settings() {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    organizationUrl: "",
    projectName: "",
    apiVersion: "",
  });
  const [repositories, setRepositories] = useState<any[]>([]);
  const { toast } = useToast();

  // Artifacts Organizations Query
  const { data: artifactOrgsData, error: artifactOrgsError } = useQuery<{ organizations: ArtifactsOrganization[] }>({
    queryKey: ["/api/artifact-organizations"],
    retry: false,
  });

  const artifactsOrgs = artifactOrgsData?.organizations || [];
  const isEncryptionAvailable = !artifactOrgsError;

  const [addOrgDialogOpen, setAddOrgDialogOpen] = useState(false);
  const [newOrgData, setNewOrgData] = useState({
    name: "",
    organizationUrl: "",
    patToken: ""
  });
  const [configurePATDialogOpen, setConfigurePATDialogOpen] = useState(false);
  const [editingOrgId, setEditingOrgId] = useState<string | null>(null);
  const [patTokenInput, setPATTokenInput] = useState("");

  // Golden Repo Organizations Query
  const { data: goldenRepoOrgsData } = useQuery<{ organizations: GoldenRepoOrganization[] }>({
    queryKey: ["/api/golden-repo-organizations"],
  });

  const goldenRepoOrgs = goldenRepoOrgsData?.organizations || [];

  // Golden Repo state
  const [addGoldenRepoDialogOpen, setAddGoldenRepoDialogOpen] = useState(false);
  const [editGoldenRepoDialogOpen, setEditGoldenRepoDialogOpen] = useState(false);
  const [editingGoldenRepoId, setEditingGoldenRepoId] = useState<string | null>(null);
  const [goldenRepoFormData, setGoldenRepoFormData] = useState({
    name: "",
    organizationUrl: "",
    projectName: "",
    repositoryName: "",
    apiVersion: "7.1",
    patToken: ""
  });

  // Fetch ADO settings
  const { data: adoSettings, isLoading } = useQuery<AdoSettings & { patConfigured?: boolean }>({
    queryKey: ["/api/ado-settings"],
  });

  // Test connection mutation
  const testConnectionMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("POST", "/api/ado-settings/test-connection");
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Connection Successful",
        description: "Successfully connected to Azure DevOps",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Connection Failed",
        description: error.message || "Failed to connect to Azure DevOps",
        variant: "destructive",
      });
    },
  });

  // Show all repositories mutation
  const showRepositoriesMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch("/api/ado-settings/repositories", {
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to fetch repositories");
      return response.json();
    },
    onSuccess: (data: any) => {
      const repos = data?.repositories || [];
      setRepositories(repos);
      toast({
        title: "Repositories Retrieved",
        description: `Found ${repos.length} repositories in Azure DevOps`,
      });
    },
    onError: (error: any) => {
      setRepositories([]);
      toast({
        title: "Failed to Fetch Repositories",
        description: error.message || "Could not retrieve repositories from Azure DevOps",
        variant: "destructive",
      });
    },
  });

  // Save settings mutation
  const saveSettingsMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const method = adoSettings ? "PUT" : "POST";
      const url = adoSettings ? `/api/ado-settings/${adoSettings.id}` : "/api/ado-settings";
      const response = await apiRequest(method, url, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/ado-settings"] });
      setIsEditing(false);
      toast({
        title: "Settings Saved",
        description: "Azure DevOps settings have been updated successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Save Failed",
        description: error.message || "Failed to save Azure DevOps settings",
        variant: "destructive",
      });
    },
  });

  const handleEdit = () => {
    if (adoSettings) {
      setFormData({
        organizationUrl: adoSettings.organizationUrl,
        projectName: adoSettings.projectName,
        apiVersion: adoSettings.apiVersion,
      });
    } else {
      setFormData({
        organizationUrl: "https://dev.azure.com/DevXPlatform/",
        projectName: "NousAugmentedDevX",
        apiVersion: "7.0",
      });
    }
    setIsEditing(true);
  };

  const handleCancel = () => {
    setIsEditing(false);
    setFormData({
      organizationUrl: "",
      projectName: "",
      apiVersion: "",
    });
  };

  const handleSave = () => {
    saveSettingsMutation.mutate(formData);
  };

  const handleTestConnection = () => {
    testConnectionMutation.mutate();
  };

  const handleShowRepositories = () => {
    showRepositoriesMutation.mutate();
  };

  // Create artifact organization mutation
  const createArtifactOrgMutation = useMutation({
    mutationFn: async (data: { name: string; organizationUrl: string; patToken?: string }) => {
      const response = await apiRequest("POST", "/api/artifact-organizations", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/artifact-organizations"] });
      setNewOrgData({ name: "", organizationUrl: "", patToken: "" });
      setAddOrgDialogOpen(false);
      toast({
        title: "Organization Added",
        description: "Organization has been added successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Add Organization",
        description: error.message || "Could not add organization",
        variant: "destructive",
      });
    },
  });

  // Artifacts Organization Handlers
  const handleAddOrganization = () => {
    if (!newOrgData.name || !newOrgData.organizationUrl) {
      toast({
        title: "Validation Error",
        description: "Please fill in all fields",
        variant: "destructive",
      });
      return;
    }

    createArtifactOrgMutation.mutate(newOrgData);
  };

  // Delete artifact organization mutation
  const deleteArtifactOrgMutation = useMutation({
    mutationFn: async (id: string) => {
      const response = await apiRequest("DELETE", `/api/artifact-organizations/${id}`);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/artifact-organizations"] });
      toast({
        title: "Organization Removed",
        description: "Organization has been removed successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Remove Organization",
        description: error.message || "Could not remove organization",
        variant: "destructive",
      });
    },
  });

  const handleRemoveOrganization = (id: string) => {
    deleteArtifactOrgMutation.mutate(id);
  };

  const handleConfigurePAT = (orgId: string) => {
    setEditingOrgId(orgId);
    setPATTokenInput("");
    setConfigurePATDialogOpen(true);
  };

  // Update artifact organization mutation (for PAT configuration)
  const updateArtifactOrgMutation = useMutation({
    mutationFn: async ({ id, patToken }: { id: string; patToken: string }) => {
      const response = await apiRequest("PUT", `/api/artifact-organizations/${id}`, { patToken });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/artifact-organizations"] });
      setConfigurePATDialogOpen(false);
      setEditingOrgId(null);
      setPATTokenInput("");
      toast({
        title: "PAT Token Configured",
        description: "PAT token has been configured successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Configure PAT",
        description: error.message || "Could not configure PAT token",
        variant: "destructive",
      });
    },
  });

  const handleSavePAT = () => {
    if (!editingOrgId || !patTokenInput) {
      toast({
        title: "Validation Error",
        description: "Please enter a PAT token",
        variant: "destructive",
      });
      return;
    }

    updateArtifactOrgMutation.mutate({ id: editingOrgId, patToken: patTokenInput });
  };

  // Golden Repo Organization Mutations
  const createGoldenRepoOrgMutation = useMutation({
    mutationFn: async (data: typeof goldenRepoFormData) => {
      const response = await apiRequest("POST", "/api/golden-repo-organizations", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/golden-repo-organizations"] });
      setAddGoldenRepoDialogOpen(false);
      setGoldenRepoFormData({
        name: "",
        organizationUrl: "",
        projectName: "",
        repositoryName: "",
        apiVersion: "7.1",
        patToken: ""
      });
      toast({
        title: "Organization Added",
        description: "Golden Repo organization has been added successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Add Organization",
        description: error.message || "Could not add organization",
        variant: "destructive",
      });
    },
  });

  const updateGoldenRepoOrgMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof goldenRepoFormData> }) => {
      const response = await apiRequest("PUT", `/api/golden-repo-organizations/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/golden-repo-organizations"] });
      setEditGoldenRepoDialogOpen(false);
      setEditingGoldenRepoId(null);
      setGoldenRepoFormData({
        name: "",
        organizationUrl: "",
        projectName: "",
        repositoryName: "",
        apiVersion: "7.1",
        patToken: ""
      });
      toast({
        title: "Organization Updated",
        description: "Golden Repo organization has been updated successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Update Organization",
        description: error.message || "Could not update organization",
        variant: "destructive",
      });
    },
  });

  const deleteGoldenRepoOrgMutation = useMutation({
    mutationFn: async (id: string) => {
      const response = await apiRequest("DELETE", `/api/golden-repo-organizations/${id}`);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/golden-repo-organizations"] });
      toast({
        title: "Organization Removed",
        description: "Golden Repo organization has been removed successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Remove Organization",
        description: error.message || "Could not remove organization",
        variant: "destructive",
      });
    },
  });

  // Golden Repo Handlers
  const handleAddGoldenRepo = () => {
    if (!goldenRepoFormData.name || !goldenRepoFormData.organizationUrl || !goldenRepoFormData.projectName) {
      toast({
        title: "Validation Error",
        description: "Please fill in all required fields",
        variant: "destructive",
      });
      return;
    }
    createGoldenRepoOrgMutation.mutate(goldenRepoFormData);
  };

  const handleEditGoldenRepo = (org: GoldenRepoOrganization) => {
    setEditingGoldenRepoId(org.id);
    setGoldenRepoFormData({
      name: org.name,
      organizationUrl: org.organizationUrl,
      projectName: org.projectName,
      repositoryName: org.repositoryName || "",
      apiVersion: org.apiVersion,
      patToken: ""
    });
    setEditGoldenRepoDialogOpen(true);
  };

  const handleUpdateGoldenRepo = () => {
    if (!editingGoldenRepoId) return;

    const updateData: any = {
      name: goldenRepoFormData.name,
      organizationUrl: goldenRepoFormData.organizationUrl,
      projectName: goldenRepoFormData.projectName,
      repositoryName: goldenRepoFormData.repositoryName,
      apiVersion: goldenRepoFormData.apiVersion,
    };

    if (goldenRepoFormData.patToken) {
      updateData.patToken = goldenRepoFormData.patToken;
    }

    updateGoldenRepoOrgMutation.mutate({ id: editingGoldenRepoId, data: updateData });
  };

  const handleDeleteGoldenRepo = (id: string) => {
    if (confirm("Are you sure you want to delete this organization?")) {
      deleteGoldenRepoOrgMutation.mutate(id);
    }
  };

  if (isLoading) {
    return (
      <div className="flex-1 p-6">
        <div className="flex items-center justify-center h-64">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 p-6">
      <div className="mx-auto max-w-4xl space-y-6">
        <div>
          <h1 className="text-3xl font-semibold" data-testid="heading-settings">Settings</h1>
          <p className="mt-2 text-muted-foreground">Manage your application settings and integrations</p>
        </div>

        <Tabs defaultValue="golden-repo" className="w-full" data-testid="settings-tabs">
          <TabsList className="grid w-full grid-cols-5" data-testid="tabs-list">
            <TabsTrigger value="golden-repo" data-testid="tab-golden-repo">
              Golden Repository
            </TabsTrigger>
            <TabsTrigger value="sdlc" data-testid="tab-sdlc">
              SDLC
            </TabsTrigger>
            <TabsTrigger value="conversational-ui" data-testid="tab-conversational-ui">
              Conversational UI
            </TabsTrigger>
            <TabsTrigger value="workflow" data-testid="tab-workflow">
              Workflow
            </TabsTrigger>
            <TabsTrigger value="hub-artifacts" data-testid="tab-hub-artifacts">
              Hub Artifacts
            </TabsTrigger>
          </TabsList>

          {/* Golden Repository Settings Tab */}
          <TabsContent value="golden-repo" className="space-y-6">
            <Card data-testid="card-golden-repo-settings">
              <CardHeader>
                <div className="flex flex-wrap items-center justify-between gap-4">
                  <div>
                    <CardTitle data-testid="heading-golden-repo-settings">Golden Repository Organizations</CardTitle>
                    <CardDescription>
                      Manage your Azure DevOps organizations for golden repository templates
                    </CardDescription>
                  </div>
                  <Button
                    onClick={() => setAddGoldenRepoDialogOpen(true)}
                    data-testid="button-add-golden-repo-org"
                  >
                    <Plus className="mr-2 h-4 w-4" />
                    Add Organization
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                {goldenRepoOrgs.length === 0 ? (
                  <div className="text-center py-12 text-muted-foreground">
                    <p data-testid="text-no-organizations">No organizations configured</p>
