import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { Edit, X, CheckCircle2, Calendar, User, Target } from "lucide-react";
import { useState } from "react";
import { WorkItemEditDialog } from "./work-item-edit-dialog";

interface WorkItemDetailsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  item: any;
  itemType: "story" | "requirement" | "backlog" | "document" | "epic";
  projectId: string;
  phaseNumber: number;
}

export function WorkItemDetailsDialog({
  open,
  onOpenChange,
  item,
  itemType,
  projectId,
  phaseNumber,
}: WorkItemDetailsDialogProps) {
  const [editDialogOpen, setEditDialogOpen] = useState(false);

  if (!item) return null;

  const getStatusColor = (status: string) => {
    switch (status?.toLowerCase()) {
      case "done":
      case "completed":
        return "default";
      case "in_progress":
      case "in-progress":
        return "secondary";
      default:
        return "outline";
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority?.toLowerCase()) {
      case "high":
        return "destructive";
      case "medium":
        return "secondary";
      default:
        return "outline";
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-3xl max-h-[90vh] p-0">
          <DialogHeader className="p-6 pb-4">
            <div className="flex items-start justify-between gap-4">
              <div className="flex-1">
                <DialogTitle className="text-xl font-semibold pr-8">
                  {item.title}
                </DialogTitle>
                <div className="flex items-center gap-2 mt-3">
                  {item.status && (
                    <Badge variant={getStatusColor(item.status)} data-testid="badge-item-status">
                      {item.status}
                    </Badge>
                  )}
                  {item.priority && (
                    <Badge variant={getPriorityColor(item.priority)} data-testid="badge-item-priority">
                      {item.priority}
                    </Badge>
                  )}
                  {item.type && (
                    <Badge variant="outline" data-testid="badge-item-type">
                      {item.type}
                    </Badge>
                  )}
                  {item.storyPoints && (
                    <Badge variant="outline" data-testid="badge-story-points">
                      <Target className="h-3 w-3 mr-1" />
                      {item.storyPoints} points
                    </Badge>
                  )}
                </div>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setEditDialogOpen(true)}
                data-testid="button-edit-item"
              >
                <Edit className="h-4 w-4 mr-2" />
                Edit
              </Button>
            </div>
          </DialogHeader>

          <Separator />

          <ScrollArea className="flex-1 px-6 pb-6">
            <div className="space-y-6 pt-4">
              {/* Description */}
              {item.description && (
                <div>
                  <h3 className="text-sm font-semibold mb-2">Description</h3>
                  <div className="text-sm text-muted-foreground whitespace-pre-wrap bg-muted/50 p-4 rounded-md">
                    {item.description}
                  </div>
                </div>
              )}

              {/* Metadata */}
              <div className="grid grid-cols-2 gap-4">
                {item.assignedTo && (
                  <div>
                    <h3 className="text-sm font-semibold mb-2 flex items-center gap-2">
                      <User className="h-4 w-4" />
                      Assigned To
                    </h3>
                    <p className="text-sm text-muted-foreground">{item.assignedTo}</p>
                  </div>
                )}
                {item.createdAt && (
                  <div>
                    <h3 className="text-sm font-semibold mb-2 flex items-center gap-2">
                      <Calendar className="h-4 w-4" />
                      Created
                    </h3>
                    <p className="text-sm text-muted-foreground">
                      {new Date(item.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                )}
              </div>

              {/* Acceptance Criteria */}
              {item.acceptanceCriteria && item.acceptanceCriteria.length > 0 && (
                <div>
                  <h3 className="text-sm font-semibold mb-3">Acceptance Criteria</h3>
                  <div className="space-y-3">
                    {item.acceptanceCriteria.map((ac: any, idx: number) => (
                      <Card key={idx} className="bg-muted/30">
                        <CardHeader className="p-3 pb-2">
                          <CardTitle className="text-sm font-medium flex items-start gap-2">
                            <CheckCircle2 className="h-4 w-4 mt-0.5 text-green-600 flex-shrink-0" />
                            {ac.title || `Acceptance Criterion ${idx + 1}`}
                          </CardTitle>
                        </CardHeader>
                        <CardContent className="p-3 pt-0 space-y-2 text-sm">
                          {ac.given && (
                            <div>
                              <span className="font-medium text-blue-600">Given:</span>{" "}
                              <span className="text-muted-foreground">{ac.given}</span>
                            </div>
                          )}
                          {ac.when && (
                            <div>
                              <span className="font-medium text-purple-600">When:</span>{" "}
                              <span className="text-muted-foreground">{ac.when}</span>
                            </div>
                          )}
                          {ac.then && (
                            <div>
                              <span className="font-medium text-green-600">Then:</span>{" "}
                              <span className="text-muted-foreground">{ac.then}</span>
                            </div>
                          )}
                          {ac.and && (
                            <div>
                              <span className="font-medium text-orange-600">And:</span>{" "}
                              <span className="text-muted-foreground">{ac.and}</span>
                            </div>
                          )}
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                </div>
              )}

              {/* Subtasks */}
              {item.subtasks && item.subtasks.length > 0 && (
                <div>
                  <h3 className="text-sm font-semibold mb-3">Subtasks</h3>
                  <div className="space-y-2">
                    {item.subtasks.map((subtask: string, idx: number) => (
                      <div 
                        key={idx} 
                        className="flex items-start gap-2 text-sm p-2 rounded-md bg-muted/30"
                        data-testid={`subtask-${idx}`}
                      >
                        <CheckCircle2 className="h-4 w-4 mt-0.5 text-muted-foreground flex-shrink-0" />
                        <span className="text-muted-foreground">{subtask}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Content (for documents) */}
              {item.content && (
                <div>
                  <h3 className="text-sm font-semibold mb-2">Content</h3>
                  <div className="text-sm text-muted-foreground whitespace-pre-wrap bg-muted/50 p-4 rounded-md">
                    {item.content}
                  </div>
                </div>
              )}

              {/* Category (for requirements) */}
              {item.category && (
                <div>
                  <h3 className="text-sm font-semibold mb-2">Category</h3>
                  <Badge variant="outline">{item.category}</Badge>
                </div>
              )}
            </div>
          </ScrollArea>
        </DialogContent>
      </Dialog>

      {/* Edit Dialog */}
      <WorkItemEditDialog
        open={editDialogOpen}
        onOpenChange={setEditDialogOpen}
        item={item}
        itemType={itemType}
        projectId={projectId}
        phaseNumber={phaseNumber}
      />
    </>
  );
}

client/src/components/work-item-edit-dia.content:
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Save, Sparkles, Loader2 } from "lucide-react";
import { useState, useEffect } from "react";
import { useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface WorkItemEditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  item: any;
  itemType: "story" | "requirement" | "backlog" | "document" | "epic";
  projectId: string;
  phaseNumber: number;
}

export function WorkItemEditDialog({
  open,
  onOpenChange,
  item,
  itemType,
  projectId,
  phaseNumber,
}: WorkItemEditDialogProps) {
  const { toast } = useToast();
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    status: "todo",
    priority: "medium",
    assignedTo: "",
    storyPoints: "",
    category: "",
    content: "",
  });

  useEffect(() => {
    if (item && open) {
      setFormData({
        title: item.title || "",
        description: item.description || "",
        status: item.status || "todo",
        priority: item.priority || "medium",
        assignedTo: item.assignedTo || "",
        storyPoints: item.storyPoints?.toString() || "",
        category: item.category || "",
        content: item.content || "",
      });
    }
  }, [item, open]);

  const updateMutation = useMutation({
    mutationFn: async (data: any) => {
      let endpoint = "";
      switch (itemType) {
        case "story":
        case "backlog":
          endpoint = `/api/sdlc/projects/${projectId}/phases/${phaseNumber}/backlog/${item.id}`;
          break;
        case "requirement":
          endpoint = `/api/sdlc/projects/${projectId}/phases/${phaseNumber}/requirements/${item.id}`;
          break;
        case "document":
          endpoint = `/api/sdlc/projects/${projectId}/phases/${phaseNumber}/documents/${item.id}`;
          break;
        case "epic":
          endpoint = `/api/sdlc/projects/${projectId}/epics/${item.id}`;
          break;
      }

      const response = await fetch(endpoint, {
        method: "PATCH",
        body: JSON.stringify(data),
        headers: { "Content-Type": "application/json" },
        credentials: "include",
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({ message: "Failed to update item" }));
        throw new Error(error.message || "Failed to update item");
      }

      return await response.json();
    },
    onSuccess: () => {
      // Invalidate relevant queries
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/phases/${phaseNumber}/backlog`] });
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/phases/${phaseNumber}/requirements`] });
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/phases/${phaseNumber}/documents`] });
      queryClient.invalidateQueries({ queryKey: [`/api/sdlc/projects/${projectId}/epics`] });

      toast({
        title: "Success",
        description: `${itemType === "story" ? "User story" : itemType} updated successfully`,
      });
      onOpenChange(false);
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: `Failed to update ${itemType}: ${error.message}`,
        variant: "destructive",
      });
    },
  });

  // AI assistance mutation for improving descriptions
  const aiAssistMutation = useMutation({
    mutationFn: async ({ title, currentDescription }: { title: string; currentDescription: string }) => {
      const response = await fetch("/api/ai/enhance-description", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          title,
          description: currentDescription,
          itemType,
        }),
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({ message: "Failed to enhance description" }));
        throw new Error(error.message || "Failed to enhance description");
      }

      return await response.json();
    },
    onSuccess: (data) => {
      setFormData(prev => ({ ...prev, description: data.enhancedDescription }));
      toast({
        title: "Description Enhanced",
        description: "AI has improved your description",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: `Failed to enhance description: ${error.message}`,
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const updateData: any = {
      title: formData.title,
      description: formData.description,
      status: formData.status,
      priority: formData.priority,
    };

    if (formData.assignedTo) updateData.assignedTo = formData.assignedTo;
    if (formData.storyPoints) updateData.storyPoints = parseInt(formData.storyPoints);
    if (formData.category) updateData.category = formData.category;
    if (formData.content) updateData.content = formData.content;

    updateMutation.mutate(updateData);
  };

  if (!item) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle>Edit {itemType === "story" ? "User Story" : itemType}</DialogTitle>
        </DialogHeader>

        <ScrollArea className="max-h-[calc(90vh-180px)]">
          <form onSubmit={handleSubmit} className="space-y-4 pr-4">
            {/* Title */}
            <div className="space-y-2">
              <Label htmlFor="title">Title *</Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                required
                data-testid="input-edit-title"
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label htmlFor="description">Description</Label>
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  onClick={() => aiAssistMutation.mutate({ 
                    title: formData.title, 
                    currentDescription: formData.description 
                  })}
                  disabled={!formData.title || aiAssistMutation.isPending}
                  className="h-7 px-2 text-xs gap-1"
                  data-testid="button-ai-enhance"
                >
                  {aiAssistMutation.isPending ? (
                    <>
                      <Loader2 className="h-3 w-3 animate-spin" />
                      <span>Enhancing...</span>
                    </>
                  ) : (
                    <>
                      <Sparkles className="h-3 w-3" />
                      <span>AI Enhance</span>
                    </>
                  )}
                </Button>
              </div>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows={4}
                placeholder="Enter description or click AI Enhance to generate one..."
                data-testid="textarea-edit-description"
              />
            </div>

            {/* Content (for documents) */}
            {itemType === "document" && (
              <div className="space-y-2">
                <Label htmlFor="content">Content</Label>
                <Textarea
                  id="content"
                  value={formData.content}
                  onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                  rows={6}
                  data-testid="textarea-edit-content"
                />
              </div>
            )}

            {/* Category (for requirements) */}
            {itemType === "requirement" && (
              <div className="space-y-2">
                <Label htmlFor="category">Category</Label>
                <Select
                  value={formData.category}
                  onValueChange={(value) => setFormData({ ...formData, category: value })}
                >
                  <SelectTrigger data-testid="select-edit-category">
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="functional">Functional</SelectItem>
                    <SelectItem value="non-functional">Non-Functional</SelectItem>
                    <SelectItem value="business">Business</SelectItem>
                    <SelectItem value="technical">Technical</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              {/* Status */}
              <div className="space-y-2">
                <Label htmlFor="status">Status *</Label>
                <Select
                  value={formData.status}
                  onValueChange={(value) => setFormData({ ...formData, status: value })}
                >
                  <SelectTrigger data-testid="select-edit-status">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="todo">To Do</SelectItem>
                    <SelectItem value="in_progress">In Progress</SelectItem>
                    <SelectItem value="done">Done</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Priority */}
              <div className="space-y-2">
                <Label htmlFor="priority">Priority</Label>
                <Select
                  value={formData.priority}
                  onValueChange={(value) => setFormData({ ...formData, priority: value })}
                >
                  <SelectTrigger data-testid="select-edit-priority">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Assigned To & Story Points (for stories) */}
            {(itemType === "story" || itemType === "backlog") && (
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="assignedTo">Assigned To</Label>
                  <Input
                    id="assignedTo"
                    value={formData.assignedTo}
                    onChange={(e) => setFormData({ ...formData, assignedTo: e.target.value })}
                    data-testid="input-edit-assigned"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="storyPoints">Story Points</Label>
                  <Input
                    id="storyPoints"
                    type="number"
                    min="0"
                    max="100"
                    value={formData.storyPoints}
                    onChange={(e) => setFormData({ ...formData, storyPoints: e.target.value })}
                    data-testid="input-edit-points"
                  />
                </div>
              </div>
            )}
          </form>
        </ScrollArea>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            data-testid="button-cancel-edit"
          >
            Cancel
          </Button>
          <Button
            type="submit"
            onClick={handleSubmit}
            disabled={updateMutation.isPending}
            data-testid="button-save-edit"
          >
            <Save className="h-4 w-4 mr-2" />
            {updateMutation.isPending ? "Saving..." : "Save Changes"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

