  const handleOpenDialog = (persona?: Persona) => {
    if (persona) {
      setFormData(persona);
      setIsEditing(true);
    } else {
      setFormData({
        name: "",
        role: "",
        focus: "",
        color: "#3b82f6",
        painPoints: [""],
        goals: [""]
      });
      setIsEditing(false);
    }
    setDialogOpen(true);
  };

  const handleSave = () => {
    toast({
      title: isEditing ? "Persona Updated" : "Persona Created",
      description: `${formData.name} has been ${isEditing ? "updated" : "created"} successfully.`
    });
    setDialogOpen(false);
