      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {samplePersonas.map(persona => (
            <Card
              key={persona.id}
              className="hover-elevate active-elevate-2 cursor-pointer"
