              data-testid={`card-persona-${persona.id}`}
            >
              <CardHeader>
                <div className="flex items-center gap-3">
                  <div
                    className="h-12 w-12 rounded-full flex items-center justify-center text-white text-lg font-bold flex-shrink-0"
