import OpenAI from "openai";
import { AzureOpenAI } from "openai";

// Use Azure OpenAI if configured, otherwise fall back to Replit AI Integration
const useAzure =
  process.env.AZURE_OPENAI_API_KEY && process.env.AZURE_OPENAI_ENDPOINT;

const openai = useAzure
  ? new AzureOpenAI({
      apiKey: process.env.AZURE_OPENAI_API_KEY,
      endpoint: process.env.AZURE_OPENAI_ENDPOINT,
      apiVersion: process.env.AZURE_OPENAI_API_VERSION || "2024-02-01",
      deployment: process.env.AZURE_OPENAI_DEPLOYMENT,
    })
  : new OpenAI({
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
    });

/**
 * SDLC Workflow Conversational Requirement Gathering Agent
 *
 * This service is specifically designed for the SDLC Workflow page to:
 * 1. Gather requirements through conversational refinement
 * 2. Know when to stop asking questions and suggest artifact generation
 * 3. Generate agile artifacts (Epics, Features, User Stories)
 */

async function fetchBacklogContext(): Promise<string> {
  try {
    // Fetch ADO backlog for context awareness
    // Use environment-based URL or default to localhost
    const baseUrl = process.env.API_BASE_URL || "http://localhost:5000";
    const response = await fetch(`${baseUrl}/api/ado-settings/backlog`);

    if (!response.ok) {
      console.log("[Workflow AI] ADO backlog not available (this is optional)");
      return "";
    }

    const data = await response.json();

    if (!data.success || !data.backlog || data.backlog.length === 0) {
      console.log("[Workflow AI] No existing backlog items found");
      return "";
    }

    // Build a summary of existing backlog for AI context
    const summary = `## EXISTING AZURE DEVOPS BACKLOG:
You have access to the user's existing Azure DevOps backlog to avoid creating duplicates.

**Current Backlog Summary:**
- Epics: ${data.counts.epics}
- Features: ${data.counts.features}
- User Stories: ${data.counts.userStories}
- Tasks: ${data.counts.tasks}
- Bugs: ${data.counts.bugs}

**Existing Epics:**
${
  data.grouped.epics
    .slice(0, 10)
    .map((item: any) => `- [${item.id}] ${item.title} (${item.state})`)
    .join("\n") || "None"
}

**Existing Features:**
${
  data.grouped.features
    .slice(0, 10)
    .map((item: any) => `- [${item.id}] ${item.title} (${item.state})`)
    .join("\n") || "None"
}

**Existing User Stories:**
${
  data.grouped.userStories
    .slice(0, 15)
    .map((item: any) => `- [${item.id}] ${item.title} (${item.state})`)
    .join("\n") || "None"
}

**IMPORTANT:** 
- When generating artifacts, check for similar existing items
- Suggest building upon or enhancing existing work items rather than duplicating
- If similar items exist, mention them to the user and ask if they want to extend those or create new ones
`;

    console.log(
      `[Workflow AI] Loaded backlog context: ${data.totalCount} items`,
    );
    return summary;
  } catch (error) {
    console.log(
      "[Workflow AI] Could not fetch backlog context:",
      error instanceof Error ? error.message : String(error),
    );
    return "";
  }
}

export async function generateWorkflowConversationQuestion(
  conversationHistory: Array<{ role: "user" | "assistant"; content: string }>,
  capturedRequirements: any,
  currentPhase: string,
  askedQuestions: string[] = [],
  complianceGuidelines: any[] = [],
): Promise<{
  question: string;
  phase: string;
  quickReplies?: string[];
  capturedInfo?: any;
  readyToGenerate?: boolean;
}> {
  try {
    console.log("[Workflow AI] Generating conversation question");
    console.log("[Workflow AI] Current phase:", currentPhase);
    console.log(
      "[Workflow AI] Conversation history length:",
      conversationHistory.length,
    );
    console.log(
      "[Workflow AI] Previously asked questions:",
      askedQuestions.length,
    );
    console.log(
      "[Workflow AI] Compliance guidelines count:",
      complianceGuidelines.length,
    );
    // Fetch backlog context for duplicate detection
    const backlogContext = await fetchBacklogContext();

    const modelName = useAzure
      ? process.env.AZURE_OPENAI_DEPLOYMENT!
      : "gpt-4o";

    const lastUserMessage =
      conversationHistory[conversationHistory.length - 1]?.content || "";

    // Check if this is a greeting (only trigger on explicit greeting keywords)
    const isEarlyInConversation = conversationHistory.length <= 2;
    const isGreeting =
      /^\s*(hey|hi|hello|hiya|howdy|greetings|good morning|good afternoon|good evening|sup|yo|hi there|hello there)[\s,!.?]*$/i.test(
        lastUserMessage.trim(),
      );

    // Only respond with warm introduction if user explicitly greeted
    if (isEarlyInConversation && isGreeting) {
      console.log(
        "[Workflow AI] Detected greeting - providing warm introduction",
      );
      return {
        question:
          "Hello! I'm your AI assistant for capturing requirements and generating agile artifacts.\n\nI'll help you create well-structured Epics, Features, and User Stories for Azure DevOps. Let's start by understanding what you're building - could you tell me a bit about your project or the features you have in mind?",
        phase: "understanding",
        quickReplies: [
          "I want to build a web app",
          "I have a mobile app idea",
          "I need to improve an existing system",
        ],
        capturedInfo: undefined,
        readyToGenerate: false,
      };
    }

    // Check if the previous AI message asked about generating artifacts
    const previousAIMessage =
      conversationHistory.length >= 2
        ? conversationHistory[conversationHistory.length - 2]?.content || ""
        : "";
    const previousAskedAboutGeneration =
      previousAIMessage
        .toLowerCase()
        .includes("would you like me to generate") ||
      previousAIMessage.toLowerCase().includes("generate the agile artifacts");

    // CRITICAL: Detect when user explicitly wants to ADD MORE information
    // This prevents the loop from immediately offering generation again
    const userWantsToAddMore =
      lastUserMessage.toLowerCase().includes("i have more") ||
      lastUserMessage.toLowerCase().includes("more to add") ||
      lastUserMessage.toLowerCase().includes("add more") ||
      lastUserMessage.toLowerCase().includes("not yet") ||
      lastUserMessage.toLowerCase().includes("wait") ||
      lastUserMessage.toLowerCase().includes("hold on") ||
      lastUserMessage.toLowerCase() === "option 2";

    // If user wants to add more, explicitly continue conversation
    if (userWantsToAddMore && previousAskedAboutGeneration) {
      console.log(
        "[Workflow AI] User wants to add more information - continuing conversation",
      );
      // Do NOT offer generation for at least 2 more questions
      // Continue to AI system prompt below to ask next question
    }

    // CRITICAL: Detect when user explicitly confirms they want to generate artifacts
    // Broadened to accept simple affirmative responses when previous message asked about generation
    const isSimpleAffirmative =
      /^\s*(yes|yep|yeah|sure|okay|ok|please do|go ahead|proceed|let's do it)\b/i.test(
        lastUserMessage.trim(),
      );

    const userConfirmedGeneration =
      (previousAskedAboutGeneration && isSimpleAffirmative) ||
      lastUserMessage.toLowerCase().includes("yes, generate artifacts") ||
      lastUserMessage.toLowerCase().includes("yes generate") ||
      lastUserMessage.toLowerCase().includes("please generate artifacts") ||
      lastUserMessage.toLowerCase().includes("generate the artifacts") ||
      lastUserMessage.toLowerCase().includes("let's generate") ||
      (lastUserMessage.toLowerCase().includes("yes") &&
        lastUserMessage.toLowerCase().includes("artifact")) ||
      lastUserMessage.toLowerCase() === "option 1";

    // If user confirmed generation, return readyToGenerate immediately
    if (userConfirmedGeneration && previousAskedAboutGeneration) {
      console.log(
        "[Workflow AI] User confirmed artifact generation - returning readyToGenerate=true",
      );
      return {
        question:
          "Perfect! Let me generate the artifacts based on our discussion. This may take a moment...",
        phase: "artifacts",
        quickReplies: [],
        readyToGenerate: true,
        capturedInfo: undefined,
      };
    }

    // Detect explicit "no" responses
    const userSaidNo =
      /^(no|nope|nah|not really|don't need|not applicable|skip|none)/i.test(
        lastUserMessage.trim(),
      );

    // Check if last question was generic "anything else"
    const lastQuestion = askedQuestions[askedQuestions.length - 1] || "";
    const lastWasGeneric =
      lastQuestion.toLowerCase().includes("anything else") ||
      lastQuestion.toLowerCase().includes("is there");

    // INTELLIGENT STOPPING LOGIC
    const hasAnyInfo =
      (capturedRequirements.targetUsers &&
        capturedRequirements.targetUsers.length > 0) ||
      (capturedRequirements.businessGoals &&
        capturedRequirements.businessGoals.length > 0) ||
      (capturedRequirements.keyFeatures &&
        capturedRequirements.keyFeatures.length > 0) ||
      (capturedRequirements.functionalRequirements &&
        capturedRequirements.functionalRequirements.length > 0);

    const hasMinimumInfo =
      capturedRequirements.targetUsers &&
      capturedRequirements.targetUsers.length > 0 &&
      ((capturedRequirements.keyFeatures &&
        capturedRequirements.keyFeatures.length > 0) ||
        (capturedRequirements.functionalRequirements &&
          capturedRequirements.functionalRequirements.length > 0));

    const tooManyQuestions = askedQuestions.length >= 6;
    const wayTooManyQuestions = askedQuestions.length >= 8;
    const userSaidNoToGeneric = userSaidNo && lastWasGeneric;

    // STOP conditions - offer to generate if ANY is true:
    // BUT: Do NOT offer if user just said they want to add more
    const shouldOfferGeneration =
      !userWantsToAddMore &&
      (userSaidNoToGeneric ||
        (tooManyQuestions && hasAnyInfo) ||
        wayTooManyQuestions ||
        (hasMinimumInfo && askedQuestions.length >= 5));

    if (shouldOfferGeneration) {
      console.log(
        "[Workflow AI] STOPPING question loop - offering artifact generation",
      );
      console.log("[Workflow AI] Reason:", {
        userSaidNoToGeneric,
        tooManyQuestions,
        wayTooManyQuestions,
        totalQuestions: askedQuestions.length,
        hasAnyInfo,
        hasMinimumInfo,
      });

      return {
        question:
          "Great! I think we have enough information to get started. Would you like me to generate the agile artifacts (Epics, Features, and User Stories) based on what we've discussed?",
        phase: currentPhase,
        quickReplies: ["Yes, generate artifacts", "I have more to add"],
        capturedInfo: undefined,
        readyToGenerate: false, // Will be set to true when user confirms
      };
    }

    // Build system prompt for SDLC workflow requirement gathering
    const systemPrompt = `# SDLC Workflow Requirement Gathering Agent — Enterprise Edition

## YOUR ROLE:
You are an **intelligent, collaborative, and friendly AI assistant** specialized in gathering software requirements through conversational refinement. You act as an experienced Product Owner and Business Analyst, helping users create **enterprise-grade Agile artifacts** (Epics, Features, User Stories) for Azure DevOps.

Your mission: Engage in a smart, contextual conversation to extract high-quality requirements that will generate production-ready work items following organizational compliance standards.

---

CORE BEHAVIOR PRINCIPLES:

### 1️⃣ Conversational Excellence
- **Be warm, friendly, and collaborative** — You're a helpful teammate, not a robotic interviewer
- **Ask ONE focused question at a time** — Never overwhelm with multiple questions
- **Keep responses concise** — 2-3 sentences maximum (unless greeting or explaining)
