import { createContext, useContext, useEffect, useState } from "react";
import { useQuery } from "@tanstack/react-query";

interface AdoSettings {
  id: string;
  organizationUrl: string;
  projectName: string;
  apiVersion: string;
  patConfigured: boolean;
  createdAt: string;
  updatedAt: string;
}

interface GoldenRepoOrganization {
  id: string;
  name: string;
  organizationUrl: string;
  projectName: string;
  repositoryName: string;
  apiVersion: string;
  patConfigured: boolean;
  createdAt: string;
  updatedAt: string;
}

interface ArtifactOrganization {
  id: string;
  name: string;
  organizationUrl: string;
  projectName: string;
  patConfigured: boolean;
  createdAt: string;
  updatedAt: string;
}

interface ConversationalUiSettings {
  id: string;
  organizationUrl: string | null;
  projectName: string | null;
  repositoryName: string | null;
  patConfigured: boolean;
}

interface WorkflowSettings {
  id: string;
  organizationUrl: string | null;
  projectName: string | null;
  repositoryName: string | null;
  patConfigured: boolean;
}

interface SdlcSettings {
  id: string;
  defaultPhaseCount: number;
  enableAutoProgress: boolean;
  requirePhaseApproval: boolean;
  createdAt: string;
  updatedAt: string;
}

interface SettingsContextType {
  adoSettings: AdoSettings | null;
  goldenRepoOrganizations: GoldenRepoOrganization[];
  artifactOrganizations: ArtifactOrganization[];
  conversationalUiSettings: ConversationalUiSettings | null;
  workflowSettings: WorkflowSettings | null;
  sdlcSettings: SdlcSettings | null;
  isLoading: boolean;
  isError: boolean;
  refetch: () => void;
}

const SettingsContext = createContext<SettingsContextType | null>(null);

export function SettingsProvider({ children }: { children: React.ReactNode }) {
  const [adoSettings, setAdoSettings] = useState<AdoSettings | null>(null);
  const [goldenRepoOrganizations, setGoldenRepoOrganizations] = useState<GoldenRepoOrganization[]>([]);
  const [artifactOrganizations, setArtifactOrganizations] = useState<ArtifactOrganization[]>([]);
  const [conversationalUiSettings, setConversationalUiSettings] = useState<ConversationalUiSettings | null>(null);
  const [workflowSettings, setWorkflowSettings] = useState<WorkflowSettings | null>(null);
  const [sdlcSettings, setSdlcSettings] = useState<SdlcSettings | null>(null);

  // Fetch ADO Settings
  const { data: adoData, isLoading: adoLoading, refetch: refetchAdo } = useQuery<AdoSettings>({
    queryKey: ['/api/ado-settings'],
  });

  // Fetch Golden Repo Organizations
  const { data: goldenRepoData, isLoading: goldenRepoLoading, refetch: refetchGoldenRepo } = useQuery<GoldenRepoOrganization[]>({
    queryKey: ['/api/golden-repo-organizations'],
  });

  // Fetch Artifact Organizations
  const { data: artifactData, isLoading: artifactLoading, refetch: refetchArtifact } = useQuery<ArtifactOrganization[]>({
    queryKey: ['/api/artifact-organizations'],
  });

  // Fetch Conversational UI Settings
  const { data: conversationalData, isLoading: conversationalLoading, refetch: refetchConversational } = useQuery<ConversationalUiSettings>({
    queryKey: ['/api/conversational-ui-settings'],
  });

  // Fetch Workflow Settings
  const { data: workflowData, isLoading: workflowLoading, refetch: refetchWorkflow } = useQuery<WorkflowSettings>({
    queryKey: ['/api/workflow-settings'],
  });

  // Fetch SDLC Settings
  const { data: sdlcData, isLoading: sdlcLoading, refetch: refetchSdlc } = useQuery<SdlcSettings>({
    queryKey: ['/api/sdlc-settings'],
  });

  // Update state when data is fetched
  useEffect(() => {
    if (adoData) setAdoSettings(adoData);
  }, [adoData]);

  useEffect(() => {
    if (goldenRepoData) setGoldenRepoOrganizations(goldenRepoData);
  }, [goldenRepoData]);

  useEffect(() => {
    if (artifactData) setArtifactOrganizations(artifactData);
  }, [artifactData]);

  useEffect(() => {
    if (conversationalData) setConversationalUiSettings(conversationalData);
  }, [conversationalData]);

  useEffect(() => {
    if (workflowData) setWorkflowSettings(workflowData);
  }, [workflowData]);

  useEffect(() => {
    if (sdlcData) setSdlcSettings(sdlcData);
  }, [sdlcData]);

  const isLoading = adoLoading || goldenRepoLoading || artifactLoading || conversationalLoading || workflowLoading || sdlcLoading;
  const isError = false; // Individual queries handle their own errors

  const refetch = () => {
    refetchAdo();
    refetchGoldenRepo();
    refetchArtifact();
    refetchConversational();
    refetchWorkflow();
    refetchSdlc();
  };

  const value: SettingsContextType = {
    adoSettings,
    goldenRepoOrganizations,
    artifactOrganizations,
    conversationalUiSettings,
    workflowSettings,
    sdlcSettings,
    isLoading,
    isError,
    refetch,
  };

  return (
    <SettingsContext.Provider value={value}>
      {children}
    </SettingsContext.Provider>
  );
}

export function useSettings() {
  const context = useContext(SettingsContext);
  if (!context) {
    throw new Error("useSettings must be used within a SettingsProvider");
  }
  return context;
}

